function notificationExportDialog92(){
 const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'}),first=today.slice(0,8)+'01';
 modal('匯出通知紀錄','<div class="notification-export-grid92"><label class="field">開始日期<input type="date" name="from" value="'+first+'" required></label><label class="field">結束日期<input type="date" name="to" value="'+today+'" required></label><label class="field">通知分類<select name="category"><option value="">全部分類</option><option>工作排程</option><option>工作回報</option><option>料件紀錄</option><option>線材提醒</option><option>電鍍提醒</option><option>假日提醒</option><option>停班提醒</option><option>自訂提醒</option></select></label><label class="field">發送狀態<select name="status"><option value="">全部狀態</option><option value="sent">成功</option><option value="failed">失敗</option><option value="pending">等待／延後</option></select></label><label class="notification-wide88"><input type="checkbox" name="tests"> 包含測試通知紀錄</label></div>','匯出 Excel',async form=>{if(!window.XLSX)throw Error('Excel元件尚未載入，請重新整理');const from=String(form.get('from')),to=String(form.get('to')),category=String(form.get('category')||''),status=String(form.get('status')||''),response=await apiFetch('/api/notification-logs?export=1&from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to)),data=await response.json();if(!response.ok)throw Error(data.error||'通知紀錄匯出失敗');const rows=(data.items||[]).filter(row=>(!category||row.category===category)&&(!status||row.status===status)),header=['發送時間','分類','標題','訊息內容','接收人員','裝置名稱','裝置類型','發送狀態','成功時間','重試次數','失敗原因'],toRows=list=>[header,...list.map(row=>[receiptTime(row.created_at),row.category,row.title,row.message,row.employee_name||'已移除人員',row.deviceLabel,row.userAgent,row.status==='sent'?'成功':row.status==='failed'?'失敗':'等待／延後',row.sent_at?receiptTime(row.sent_at):'',Number(row.retry_count||0),row.error_message||''])],book=XLSX.utils.book_new(),append=(name,list)=>{const sheet=XLSX.utils.aoa_to_sheet(toRows(list));sheet['!cols']=[18,12,28,48,14,24,35,12,18,10,45].map(w=>({wch:w}));XLSX.utils.book_append_sheet(book,sheet,name)};append('通知總覽',rows);for(const [name,types]of [['工作相關',['work','report']],['料件相關',['material']],['線材電鍍',['wire','plating']],['假日停班',['holiday','closure']],['自訂通知',['custom']]])append(name,rows.filter(row=>types.includes(row.notification_type)));if(form.get('tests')){const tests=data.testAudits||[],sheet=XLSX.utils.aoa_to_sheet([['時間','操作者','接收對象','標題','內容','裝置數','成功','失敗','來源','操作裝置'],...tests.map(item=>[receiptTime(item.created_at),item.actor_name,item.target_employee,item.title,item.message,item.device_count,item.sent_count,item.failed_count,item.source_page||'manual-test',item.user_agent])]);sheet['!cols']=[18,14,14,30,48,10,10,10,24,40].map(w=>({wch:w}));XLSX.utils.book_append_sheet(book,sheet,'測試通知')}XLSX.writeFile(book,'通知紀錄_'+from+'_至_'+to+'.xlsx');$('#modal').close();toast('通知紀錄已匯出')});
}

const notificationDevicesDialogBefore92=notificationDevicesDialog82;
notificationDevicesDialog82=async function(){await notificationDevicesDialogBefore92();const box=$('#notification-device-list82');if(!box)return;box.querySelectorAll('[data-notification-device-delete82]').forEach(remove=>{const rename=document.createElement('button');rename.type='button';rename.textContent='重新命名';rename.onclick=async()=>{const row=remove.closest('.admin-row'),old=row.querySelector('strong')?.textContent||'',name=prompt('輸入裝置名稱',old);if(name===null||!name.trim())return;const response=await apiFetch('/api/push-subscription?admin=1',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:remove.dataset.notificationDeviceDelete82,deviceLabel:name.trim()})}),data=await response.json();if(!response.ok)return toast(data.error||'重新命名失敗');$('#modal').close();notificationDevicesDialog82();toast('裝置名稱已更新')};remove.before(rename)})};

